def read_count(prompt):
    while True:
        entry = input(prompt).strip()
        if entry.isascii() and entry.isdecimal():
            return int(entry)
        print("Enter a nonnegative whole number.")


student_count = read_count("Number of names: ")
test_count = read_count("Number of tests: ")
scores = {}
while len(scores) < student_count:
    name = input("Fictional name: ").strip().lower()
    if name and name not in scores:
        scores[name] = []
    else:
        print("Enter a new, nonempty name.")

for test in range(1, test_count + 1):
    for name, results in scores.items():
        score = read_count(f"Score for {name} on test {test}: ")
        while score > 100:
            print("Use a score from 0 through 100.")
            score = read_count(f"Score for {name} on test {test}: ")
        results.append(score)

if not scores:
    print("No names entered.")
for name, results in scores.items():
    print(f"{name} scores: {results}")
    if results:
        print(f"{name} average: {sum(results) / len(results):g}")
    else:
        print(f"{name}: No scores.")

PS9-Wheel-of-Fortune/solution/main.py.content:
target = "programming"
target_letters = set(target)
attempts = set()
remaining = 15


def reveal(word, guesses):
    visible = []
    for letter in word:
        visible.append(letter if letter in guesses else "_")
    return " ".join(visible)


while remaining > 0:
    print(reveal(target, attempts))
    guess = input(f"Guess a letter ({remaining} remaining): ").strip().lower()
    if len(guess) != 1 or not guess.isascii() or not guess.isalpha():
        print("Enter one letter from A to Z.")
        continue
    if guess in attempts:
        print("That letter has already been guessed.")
        continue
    attempts.add(guess)
    remaining -= 1
    if target_letters.issubset(attempts):
        print(reveal(target, attempts))
        print(f"Puzzle solved in {15 - remaining} guesses!")
        break
else:
    print(f"No guesses remain. The word was {target}.")

