def register(signups, capacity):
    seen = set()
    enrolled = []
    waiting = []
    for name in signups:
        if name in seen:
            continue
        seen.add(name)
        if len(enrolled) < capacity:
            enrolled.append(name)
        else:
            waiting.append(name)
    return enrolled, waiting


